public void processSMCActivateOnRegistrationResponse(final ExternalServiceModel service, final SMCDeviceResponse response) {

    // Setting first registration id in this field, avoiding setting it if already existent

    final String registrationId = response.getMobilecare_serial_number();

    if (StringUtils.isBlank(service.getProviderRegistrationId())) {

        service.setProviderRegistrationId(registrationId);

    }


    // List of keys and values that will be added as provider parameters

    final Map < String, String > parametersToAdd = new HashMap < > ();


    // Add all the response parameters (put here all used response fields)

    parametersToAdd.put(TokosmcservicesConstants.SMC_RESPONSE_PARAM_PROVIDER_REGISTRATION_ID, registrationId);

    parametersToAdd.put(TokosmcservicesConstants.SMC_RESPONSE_PARAM_SERIAL_NUMBER, registrationId);

    parametersToAdd.put(TokosmcservicesConstants.SMC_RESPONSE_PARAM_STATUS_CODE, response.getStatus_code());

    parametersToAdd.put(TokosmcservicesConstants.SMC_RESPONSE_PARAM_POLICY_ID, response.getPolicy_id());

    parametersToAdd.put(TokosmcservicesConstants.SMC_RESPONSE_PARAM_CERTIFICATE_NUMBER, response.getMobilecare_certificate_number());


    // Saving parameters

    SMCExternalServicesUtilities.saveResponseParameters(modelService, service, parametersToAdd);

    println("SC+ response saved successfully")


    if (service.status.code != 'UPDATED') {

        println("Status changed to UPDATED from " + service.status.code)

        service.setStatus(ExternalServiceStatus.UPDATED);

        modelService.save(service);

    }

}
